import {
  HINDI_TABLE_RECITATION,
  GUJARATI_TABLE_RECITATION,
  HINDI_NUMBERS,
  GUJARATI_NUMBERS,
  ENGLISH_NUMBERS,
  toHiDigits,
  toGujDigits,
  formatMathExpression,
} from '../utils/languageData';

export function getLessonDisplayLabels(
  item: LessonItem,
  language: 'gu' | 'en' | 'hi'
): { primaryLabel: string; secondaryBracket: string } {
  // 1. Numbers Category (1 to 100)
  if (item.categoryId === 'numbers') {
    const match = item.id.match(/^num-(\d+)$/);
    const n = match ? parseInt(match[1], 10) : item.countItems || 0;
    if (language === 'hi') {
      return {
        primaryLabel: HINDI_NUMBERS[n] || item.title,
        secondaryBracket: '',
      };
    }
    if (language === 'gu') {
      return {
        primaryLabel: GUJARATI_NUMBERS[n] || item.exampleWord || item.title,
        secondaryBracket: '',
      };
    }
    return {
      primaryLabel: ENGLISH_NUMBERS[n] || item.exampleWord || item.title,
      secondaryBracket: '',
    };
  }

  // 2. Math Category
  if (item.categoryId === 'math') {
    const primaryLabel = formatMathExpression(item.exampleWord || item.symbol, language);
    let secondaryBracket = '';
    if (language === 'gu') {
      secondaryBracket = item.audioPromptGu || item.phonetic || '';
    } else if (language === 'hi') {
      secondaryBracket = item.audioPromptHi || item.phonetic || '';
    } else {
      secondaryBracket = item.phonetic || item.audioPromptEn || '';
    }
    return { primaryLabel, secondaryBracket };
  }

  // 2b. Math Missing Numbers & Sequence Puzzles (Explicit Answer & Question Sequence)
  if (item.categoryId === 'math-missing') {
    const match = (item.title || '').match(/→\s*(\d+)/) || (item.symbol || '').match(/(\d+)/);
    const ansNum = match ? match[1] : (item.symbol || '3');
    const n = parseInt(ansNum, 10) || 0;
    const ansGu = toGujDigits(n);
    const ansHi = toHiDigits(n);

    const titleParts = (item.title || '').split('•');
    const enSeq = titleParts[0]?.trim() || '';

    if (language === 'gu') {
      return {
        primaryLabel: `જવાબ: ${ansGu} (ખૂટતી સંખ્યા)`,
        secondaryBracket: `(${enSeq})`,
      };
    }
    if (language === 'hi') {
      return {
        primaryLabel: `उत्तर: ${ansHi} (छूटी संख्या)`,
        secondaryBracket: `(${enSeq})`,
      };
    }
    return {
      primaryLabel: `Answer: ${ansNum} (Missing Number)`,
      secondaryBracket: `(${enSeq})`,
    };
  }

  // 2c. Cognitive Patterns & Sequences (Question & Options Mode)
  if (item.id.startsWith('cs-pattern')) {
    const pz = PATTERN_PUZZLES_MAP[item.id];
    let name = '';
    if (pz?.name) {
      name = language === 'gu' ? pz.name.gu : language === 'hi' ? pz.name.hi : pz.name.en;
    } else {
      const parts = (item.title || '').split('•');
      name = language === 'hi' && parts.length >= 3 ? parts[2].trim() : language === 'gu' && parts.length >= 2 ? parts[1].trim() : parts[0].trim();
    }
    const secondaryBracket =
      language === 'gu'
        ? '(પેટર્ન પૂર્ણ કરો ❓)'
        : language === 'hi'
        ? '(पैटर्न पूरा करें ❓)'
        : '(Complete Pattern ❓)';
    return { primaryLabel: name, secondaryBracket };
  }

  // 2d. Word Problems (Clean localized story title + concise localized math equation)
  if (item.categoryId === 'math-word-problems') {
    const titleParts = (item.title || '').includes('•')
      ? item.title.split('•').map((s) => s.trim())
      : null;
    const enTitle = titleParts ? titleParts[0] : item.phonetic || item.exampleWord || item.title;
    const guTitle = titleParts?.[1] || enTitle;
    const hiTitle = titleParts?.[2] || enTitle;

    const eqMatch = (item.phonetic || item.title || '').match(/\d+\s*[+\-×÷]\s*\d+\s*=\s*\d+/);
    const shortEq = eqMatch ? formatMathExpression(eqMatch[0], language) : '';

    if (language === 'gu') {
      return {
        primaryLabel: guTitle,
        secondaryBracket: shortEq ? `(${shortEq})` : '',
      };
    }
    if (language === 'hi') {
      return {
        primaryLabel: hiTitle,
        secondaryBracket: shortEq ? `(${shortEq})` : '',
      };
    }
    return {
      primaryLabel: enTitle,
      secondaryBracket: '',
    };
  }

  // 3. English Alphabet & Phonics (Intentional English Learning)
  if (
    item.categoryId === 'en-alphabet' ||
    item.categoryId === 'en-phonics' ||
    item.language === 'en'
  ) {
    return {
      primaryLabel: item.exampleWord || item.title,
      secondaryBracket: '',
    };
  }

  // 4. Gujarati Varnamala & Barakhadi (Intentional Gujarati Script Learning)
  if (
    item.categoryId === 'gu-varnamala' ||
    item.categoryId === 'gu-barakhadi' ||
    item.language === 'gu'
  ) {
    if (language === 'en') {
      return {
        primaryLabel: item.exampleMeaning || item.title,
        secondaryBracket: item.phonetic ? `(${item.phonetic})` : '',
      };
    }
    const primaryLabel = item.exampleWord || item.symbol || item.title;
    const secondaryBracket =
      language === 'hi'
        ? item.exampleMeaningHi
          ? `(${item.exampleMeaningHi})`
          : ''
        : '';
    return { primaryLabel, secondaryBracket };
  }

  // 5. Hindi Varnamala (Intentional Hindi Script Learning)
  if (item.categoryId === 'hi-varnamala' || item.language === 'hi') {
    if (language === 'en') {
      return {
        primaryLabel: item.exampleMeaning || item.title,
        secondaryBracket: item.phonetic ? `(${item.phonetic})` : '',
      };
    }
    const primaryLabel = item.exampleWord || item.symbol || item.title;
    const secondaryBracket =
      language === 'gu'
        ? item.exampleMeaningGu
          ? `(${item.exampleMeaningGu})`
          : ''
        : '';
    return { primaryLabel, secondaryBracket };
  }

  // 6. Multilingual / Universal Categories (GK, Animals, Fruits, Objects, Colors & Shapes)
  // Check if title contains 3-part bullet separator: "English • Gujarati • Hindi"
  const titleParts = (item.title || '').includes('•')
    ? item.title.split('•').map((s) => s.trim())
    : null;

  const enName = titleParts
    ? titleParts[0]
    : item.audioPromptEn || item.phonetic || item.exampleWord || item.title;
  const guName = titleParts
    ? titleParts[1]
    : item.exampleMeaningGu || item.audioPromptGu || item.exampleWord || item.title;
  const hiName = titleParts
    ? titleParts[2]
    : item.exampleMeaningHi || item.audioPromptHi || item.exampleWord || item.title;

  if (language === 'gu') {
    return {
      primaryLabel: guName,
      secondaryBracket: enName && enName !== guName ? `(${enName})` : '',
    };
  }

  if (language === 'hi') {
    return {
      primaryLabel: hiName,
      secondaryBracket: enName && enName !== hiName ? `(${enName})` : '',
    };
  }

  // English mode: Pure English with no Gujarati/Hindi secondary bracket in general categories
  return {
    primaryLabel: enName,
    secondaryBracket: '',
  };
}

export function getLessonAudio(
  lesson: LessonItem,
  currentLanguage: 'gu' | 'en' | 'hi'
): { text: string; lang: 'gu' | 'en' | 'hi' } {
  // Multiplication Tables (Ghadiya / पहाड़े)
  if (lesson.categoryId === 'ghadiya') {
    const parts = lesson.id.split('-');
    const tNum = parseInt(parts[1], 10) || 1;
    const rNum = parseInt(parts[2], 10) || 1;

    if (currentLanguage === 'hi') {
      const chant = HINDI_TABLE_RECITATION[tNum]?.[rNum]?.audio || `${toHiDigits(tNum)} गुना ${toHiDigits(rNum)} बराबर ${toHiDigits(tNum * rNum)}`;
      return { text: chant, lang: 'hi' };
    }
    if (currentLanguage === 'en') {
      return { text: `${tNum} times ${rNum} is ${tNum * rNum}`, lang: 'en' };
    }
    const chantGu = GUJARATI_TABLE_RECITATION[tNum]?.[rNum]?.audio || lesson.audioPromptGu || `${toGujDigits(tNum)} ગુણ્યા ${toGujDigits(rNum)} બરાબર ${toGujDigits(tNum * rNum)}`;
    return { text: chantGu, lang: 'gu' };
  }

  // Numbers (1 to 100) - Clean single pronunciation (no repeated digits)
  if (lesson.categoryId === 'numbers') {
    const match = lesson.id.match(/^num-(\d+)$/);
    const n = match ? parseInt(match[1], 10) : lesson.countItems || 1;

    if (currentLanguage === 'hi') {
      const word = HINDI_NUMBERS[n] || toHiDigits(n);
      return { text: word, lang: 'hi' };
    }
    if (currentLanguage === 'en') {
      const word = ENGLISH_NUMBERS[n] || `${n}`;
      return { text: word, lang: 'en' };
    }
    const word = GUJARATI_NUMBERS[n] || lesson.exampleWord || toGujDigits(n);
    return { text: word, lang: 'gu' };
  }

  // Gujarati Varnamala (કક્કો અને સ્વર): "ક ... કમળ નો ક", "ખ ... ખલ નો ખ", etc.
  if (lesson.categoryId === 'gu-varnamala') {
    if (currentLanguage === 'en') {
      if (lesson.audioPromptEn) {
        return { text: lesson.audioPromptEn, lang: 'en' };
      }
      return {
        text: `${lesson.phonetic || lesson.symbol} for ${lesson.exampleMeaning || 'Lotus'}`,
        lang: 'en',
      };
    }
    if (lesson.audioPromptGu) {
      return { text: lesson.audioPromptGu, lang: 'gu' };
    }
    if (lesson.symbol && lesson.exampleWord) {
      const word = lesson.symbol === 'ળ' ? 'નળ' : lesson.exampleWord;
      return { text: `${lesson.symbol} ... ${word} નો ${lesson.symbol}`, lang: 'gu' };
    }
    return { text: lesson.audioPrompt, lang: 'gu' };
  }
  if (lesson.categoryId === 'gu-barakhadi') {
    if (currentLanguage === 'en') {
      if (lesson.audioPromptEn) {
        return { text: lesson.audioPromptEn, lang: 'en' };
      }
      return {
        text: `${lesson.phonetic || lesson.symbol} for ${lesson.exampleMeaning || 'Lotus'}`,
        lang: 'en',
      };
    }
    return { text: lesson.audioPromptGu || lesson.audioPrompt, lang: 'gu' };
  }
  if (lesson.categoryId === 'hi-varnamala') {
    if (currentLanguage === 'en') {
      if (lesson.audioPromptEn) {
        return { text: lesson.audioPromptEn, lang: 'en' };
      }
      return {
        text: `${lesson.phonetic || lesson.symbol} for ${lesson.exampleMeaning || 'Pigeon'}`,
        lang: 'en',
      };
    }
    return { text: lesson.audioPromptHi || lesson.audioPrompt, lang: 'hi' };
  }
  // English Alphabet: Clean single phrasing (e.g., "A for Apple" - never repeat example word at the end)
  if (lesson.categoryId === 'en-alphabet') {
    const letter = lesson.symbol || lesson.id.replace('en-alpha-', '').toUpperCase();
    const word = lesson.exampleWord || 'Apple';
    return { text: `${letter} for ${word}`, lang: 'en' };
  }
  // English Phonics: A for Apple / એ ફોર એપલ / A फॉर ऐप्पल
  if (lesson.categoryId === 'en-phonics') {
    if (currentLanguage === 'gu') {
      return { text: lesson.audioPromptGu || `${lesson.exampleWord || 'Apple'}`, lang: 'gu' };
    }
    if (currentLanguage === 'hi') {
      return { text: lesson.audioPromptHi || `${lesson.exampleWord || 'Apple'}`, lang: 'hi' };
    }
    return { text: lesson.audioPromptEn || `${lesson.symbol?.charAt(0) || 'A'} for ${lesson.exampleWord || 'Apple'}`, lang: 'en' };
  }

  // English Vowels: Vowel A / સ્વર એ / स्वर ए
  if (lesson.categoryId === 'en-vowels') {
    if (currentLanguage === 'gu') {
      return { text: lesson.audioPromptGu || `સ્વર ${lesson.symbol}`, lang: 'gu' };
    }
    if (currentLanguage === 'hi') {
      return { text: lesson.audioPromptHi || `स्वर ${lesson.symbol}`, lang: 'hi' };
    }
    return { text: lesson.audioPromptEn || `Vowel ${lesson.symbol}`, lang: 'en' };
  }

  // Animals & Birds - ensure pure animal name in active language
  if (lesson.categoryId === 'animals') {
    if (currentLanguage === 'hi') {
      const name = lesson.audioPromptHi || lesson.exampleMeaningHi || lesson.title.split('•')[2]?.trim() || lesson.title;
      return { text: name, lang: 'hi' };
    }
    if (currentLanguage === 'en') {
      const name = lesson.audioPromptEn || lesson.exampleWord || lesson.title.split('•')[0]?.trim() || lesson.title;
      return { text: name, lang: 'en' };
    }
    const name = lesson.audioPromptGu || lesson.audioPrompt || lesson.exampleMeaningGu || lesson.title.split('•')[1]?.trim() || lesson.title;
    return { text: name, lang: 'gu' };
  }

  // Universal categories (math, colors, shapes, fruits, objects, general knowledge)
  if (currentLanguage === 'gu') {
    const guFromTitle = lesson.title && lesson.title.includes('•') ? lesson.title.split('•')[1]?.trim() : null;
    return { text: lesson.audioPromptGu || guFromTitle || lesson.audioPrompt || lesson.title, lang: 'gu' };
  }
  if (currentLanguage === 'hi') {
    const hiFromTitle = lesson.title && lesson.title.includes('•') ? lesson.title.split('•')[2]?.trim() : null;
    return { text: lesson.audioPromptHi || hiFromTitle || lesson.audioPrompt || lesson.title, lang: 'hi' };
  }
  const enFromTitle = lesson.title && lesson.title.includes('•') ? lesson.title.split('•')[0]?.trim() : null;
  return { text: lesson.audioPromptEn || enFromTitle || lesson.exampleWord || lesson.phonetic || lesson.title, lang: 'en' };
}
